4	// From Apelin's command-line template. The build defines APELIN_VERSION and
5	// APELIN_BUILD_ID as string literals on every compile. Exit codes follow
6	// sysexits(3): 0 on success, 64 for a usage error.
7	#include <stdio.h>
8	#include <string.h>
9	#include <sysexits.h>
10	
11	static void print_usage(FILE *stream) {
12	    fprintf(stream, "usage: %s [--version] [--help] [name]\n", "DemoCLI");
13	}
14	
15	int main(int argc, char *argv[]) {
16	    const char *name = "world";
17	    for (int index = 1; index < argc; index++) {
18	        const char *argument = argv[index];
19	        if (strcmp(argument, "--version") == 0) {
20	            printf("%s %s (%s)\n", "DemoCLI", APELIN_VERSION, APELIN_BUILD_ID);
21	            return EX_OK;
22	        }
23	        if (strcmp(argument, "--help") == 0 || strcmp(argument, "-h") == 0) {
24	            print_usage(stdout);
25	            return EX_OK;
26	        }
27	        if (argument[0] == '-') {
28	            fprintf(stderr, "%s: unknown option %s\n", "DemoCLI", argument);
29	            print_usage(stderr);
30	            return EX_USAGE;
31	        }
32	        name = argument;
33	    }
34	    printf("Hello, %s!\n", name);
35	    return EX_OK;
36	}
